#include <array>
#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>

template <std::size_t N>
class FixedRoute {
 public:
  [[nodiscard]] std::int32_t* begin() { return legs_mm_.data(); }
  [[nodiscard]] std::int32_t* end() { return legs_mm_.data() + legs_mm_.size(); }
  [[nodiscard]] const std::int32_t* begin() const { return legs_mm_.data(); }
  [[nodiscard]] const std::int32_t* end() const { return legs_mm_.data() + legs_mm_.size(); }

 private:
  std::array<std::int32_t, N> legs_mm_{};
};

int main() {
  FixedRoute<4> route;
  std::int32_t leg = 500;
  for (std::int32_t& mm : route) {
    mm = leg;
    leg += 250;
  }

  std::int64_t total = 0;
  for (const std::int32_t mm : route) total += mm;
  std::cout << std::format("total {} mm\n", total);

  const FixedRoute<4>& view = route;
  std::int64_t again = 0;
  for (const std::int32_t mm : view) again += mm;
  std::cout << std::format("same total through a const reference: {}\n", again == total);
}

