#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>
#include <iterator>
#include <vector>

// A fixed-capacity ring: push overwrites the oldest reading once it is full.
// The iterator walks oldest to newest and hides the wraparound entirely.
class RecentReadings {
 public:
  explicit RecentReadings(std::size_t capacity) : mm_(capacity) {}

  void push(std::int32_t mm) {
    mm_[next_] = mm;
    next_ = (next_ + 1) % mm_.size();
    if (count_ < static_cast<std::ptrdiff_t>(mm_.size())) ++count_;
  }

  class Iterator {
   public:
    using iterator_category = std::forward_iterator_tag;
    using value_type = std::int32_t;
    using difference_type = std::ptrdiff_t;
    using pointer = const std::int32_t*;
    using reference = const std::int32_t&;

    Iterator() = default;
    Iterator(const std::vector<std::int32_t>* mm, std::size_t oldest, std::ptrdiff_t index)
        : mm_(mm), oldest_(oldest), index_(index) {}

    [[nodiscard]] reference operator*() const {
      return (*mm_)[(oldest_ + static_cast<std::size_t>(index_)) % mm_->size()];
    }
    Iterator& operator++() {
      ++index_;
      return *this;
    }
    Iterator operator++(int) {
      Iterator copy = *this;
      ++*this;
      return copy;
    }
    [[nodiscard]] bool operator==(const Iterator& other) const { return index_ == other.index_; }

   private:
    const std::vector<std::int32_t>* mm_ = nullptr;
    std::size_t oldest_ = 0;
    std::ptrdiff_t index_ = 0;
  };

  [[nodiscard]] Iterator begin() const { return Iterator(&mm_, oldest_index(), 0); }
  [[nodiscard]] Iterator end() const { return Iterator(&mm_, oldest_index(), count_); }

 private:
  [[nodiscard]] std::size_t oldest_index() const {
    if (count_ < static_cast<std::ptrdiff_t>(mm_.size())) return 0;
    return next_;
  }

  std::vector<std::int32_t> mm_;
  std::size_t next_ = 0;
  std::ptrdiff_t count_ = 0;
};

static_assert(std::forward_iterator<RecentReadings::Iterator>);

int main() {
  RecentReadings readings(4);
  for (const std::int32_t mm : {900, 850, 1300, 1250, 700, 640}) readings.push(mm);  // 6 pushes, capacity 4

  std::cout << "oldest to newest:";
  for (const std::int32_t mm : readings) std::cout << ' ' << mm;
  std::cout << '\n';

  const auto close = std::ranges::find_if(readings, [](std::int32_t mm) { return mm < 700; });
  std::cout << std::format("first reading under 700 mm: {}\n", close != readings.end() ? *close : -1);
}

