#include <vector>

struct Fault {
  std::string code;
  std::int64_t at_ms = 0;
};

// A fixed-capacity ring of the most recent faults. record() overwrites the oldest once full.
class FaultHistory {
 public:
  explicit FaultHistory(std::size_t capacity) : faults_(capacity) {}

  void record(Fault fault) {
    faults_[next_] = std::move(fault);
    next_ = (next_ + 1) % faults_.size();
    if (count_ < static_cast<std::ptrdiff_t>(faults_.size())) ++count_;
  }

  [[nodiscard]] std::ptrdiff_t size() const { return count_; }

  class Iterator {
   public:
    using iterator_category = std::forward_iterator_tag;
    using value_type = Fault;
    using difference_type = std::ptrdiff_t;
    using pointer = const Fault*;
    using reference = const Fault&;

    Iterator() = default;
    Iterator(const std::vector<Fault>* faults, std::size_t oldest, std::ptrdiff_t index)
        : faults_(faults), oldest_(oldest), index_(index) {}

    [[nodiscard]] reference operator*() const {
      return (*faults_)[(oldest_ + static_cast<std::size_t>(index_)) % faults_->size()];
    }
    [[nodiscard]] pointer operator->() const { return &**this; }
    Iterator& operator++() {
      ++index_;
      return *this;
    }
    Iterator operator++(int) {
      Iterator copy = *this;
      ++*this;
      return copy;
    }
    [[nodiscard]] bool operator==(const Iterator& other) const { return index_ == other.index_; }

   private:
    const std::vector<Fault>* faults_ = nullptr;
    std::size_t oldest_ = 0;
    std::ptrdiff_t index_ = 0;
  };

  [[nodiscard]] Iterator begin() const { return Iterator(&faults_, oldest_index(), 0); }
  [[nodiscard]] Iterator end() const { return Iterator(&faults_, oldest_index(), count_); }

 private:
  [[nodiscard]] std::size_t oldest_index() const {
    if (count_ < static_cast<std::ptrdiff_t>(faults_.size())) return 0;
    return next_;
  }

  std::vector<Fault> faults_;
  std::size_t next_ = 0;
  std::ptrdiff_t count_ = 0;
};

static_assert(std::forward_iterator<FaultHistory::Iterator>);

int main() {
  FaultHistory history(3);
  history.record({.code = "E_TIMEOUT", .at_ms = 100});
  history.record({.code = "E_TIMEOUT", .at_ms = 250});
  history.record({.code = "E_STALL", .at_ms = 400});
  history.record({.code = "E_LOW_BATTERY", .at_ms = 900});  // overwrites the first E_TIMEOUT

  std::cout << std::format("history holds {} of the most recent faults:\n", history.size());
  for (const Fault& fault : history) std::cout << std::format("  {} at {} ms\n", fault.code, fault.at_ms);

  const auto stall = std::ranges::find_if(history, [](const Fault& fault) { return fault.code == "E_STALL"; });
  std::cout << std::format("first E_STALL at {} ms\n", stall != history.end() ? stall->at_ms : -1);

  const auto missing = std::ranges::find_if(history, [](const Fault& fault) { return fault.code == "E_VOLTAGE"; });
  std::cout << std::format("E_VOLTAGE found: {}\n", missing != history.end());
}

