    std::ptrdiff_t index_ = 0;
  };

  [[nodiscard]] Iterator begin() const { return Iterator(&mm_, 0); }
  [[nodiscard]] Iterator end() const { return Iterator(&mm_, static_cast<std::ptrdiff_t>(mm_.size())); }

