#include <cstdint>
#include <format>
#include <iostream>
#include <vector>

// A custom collection that forwards std::vector's own iterators rather than writing new ones.
class ReadingLog {
 public:
  using iterator = std::vector<std::int32_t>::const_iterator;
  void record(std::int32_t mm) { mm_.push_back(mm); }
  [[nodiscard]] iterator begin() const { return mm_.begin(); }
  [[nodiscard]] iterator end() const { return mm_.end(); }

 private:
  std::vector<std::int32_t> mm_;
};

int main() {
  ReadingLog log;
  log.record(10);
  const auto first = log.begin();  // an iterator into a one-element vector, capacity 1
  log.record(20);                  // grows past capacity: reallocates
  std::cout << std::format("first logged reading: {}\n", *first);  // reads freed memory
}
